import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter
wb = openpyxl.load_workbook("Role shortlist - 8 Aug 2026.xlsx")
if "FDE focus" in wb.sheetnames: del wb["FDE focus"]
ws = wb.create_sheet("FDE focus", 1)
hdr=["#","Company","Role","Location / eligibility","Comp","Years asked","Stack named","Note"]
widths=[5,24,46,34,26,14,44,60]
HF=PatternFill("solid",fgColor="1F3864"); HFONT=Font(bold=True,color="FFFFFF",size=11)
HL=PatternFill("solid",fgColor="E2EFDA")
THIN=Side(style="thin",color="D9D9D9"); B=Border(left=THIN,right=THIN,top=THIN,bottom=THIN)
ws["A1"]="Forward Deployed Engineer - focused sweep, 8 August 2026"
ws["A1"].font=Font(bold=True,size=14,color="1F3864")
ws["A2"]="FDE is the title family that keeps landing in his 2-5 year band while 'AI Engineer' keeps asking 5+. This tab is every FDE and Deployment Strategist role surfaced today. Green rows are fit-scored on the Shortlist tab; the rest are leads whose postings have not been opened one by one. Germany is where the density is - a dozen employers in Berlin and Munich alone."
ws["A2"].font=Font(italic=True,size=10,color="595959"); ws["A2"].alignment=Alignment(wrap_text=True)
ws.merge_cells("A2:H2"); ws.row_dimensions[2].height=44
for c,(h,w) in enumerate(zip(hdr,widths),1):
    cell=ws.cell(row=4,column=c,value=h); cell.fill=HF; cell.font=HFONT; cell.border=B
    ws.column_dimensions[get_column_letter(c)].width=w
for i,row in enumerate(FDE,1):
    r=i+4; on = "ON THE SHORTLIST" in row[6]
    for c,v in enumerate((i,)+row,1):
        cell=ws.cell(row=r,column=c,value=v); cell.border=B
        cell.alignment=Alignment(wrap_text=(c in (3,4,7,8)),vertical="top")
        if on: cell.fill=HL
ws.freeze_panes="A5"; ws.auto_filter.ref=f"A4:H{4+len(FDE)}"
wb.save("Role shortlist - 8 Aug 2026.xlsx")
print("FDE rows:",len(FDE))
